/bin/bash -lc "python - <<'PY'
import csv, statistics
vals={}
with open('galaxy_outputs/treeness.tsv', newline='') as f:
    for row in csv.DictReader(f, delimiter='\\t'):
        if row['status'] == 'ok':
            vals.setdefault(row['group'], []).append(float(row['value']))
for group in ('fungi','animals'):
    xs=vals[group]
    print(group, 'n=',len(xs), 'median=',format(statistics.median(xs),'.10g'))
diff=statistics.median(vals['fungi'])-statistics.median(vals['animals'])
print('fungi_minus_animals=',format(diff,'.10g'))
PY"

